{
  "apiVersion": 1,
  "type": "template.show",
  "package": "@astryxdesign/core",
  "data": {
    "template": "SegmentedControlItemBasic",
    "description": "A row of label-only options that switches between a few views, here Board, List, and Timeline. Each item declares a value; the parent control holds the selected value and change handler.",
    "type": "block",
    "components": [
      "SegmentedControl"
    ],
    "source": "// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {\n  SegmentedControl,\n  SegmentedControlItem,\n} from '@astryxdesign/core/SegmentedControl';\n\nexport default function SegmentedControlItemBasic() {\n  const [view, setView] = useState('board');\n\n  return (\n    <SegmentedControl value={view} onChange={setView} label=\"View mode\">\n      <SegmentedControlItem value=\"board\" label=\"Board\" />\n      <SegmentedControlItem value=\"list\" label=\"List\" />\n      <SegmentedControlItem value=\"timeline\" label=\"Timeline\" />\n    </SegmentedControl>\n  );\n}\n",
    "demoMediaReplaced": 0,
    "demoContentReplaced": 0
  },
